local function dumpInstance(instance, log, indent)
    indent = indent or S(71)
    for _, child in ipairs(instance:GetChildren()) do
        local line = indent .. child.ClassName .. S(16) .. child.Name .. S(68)
        if child:IsA(S(90)) then
            line = line .. string.format(
                S(188),
                child.ActionText, child.ObjectText, tostring(child.HoldDuration)
            )
        elseif child:IsA(S(179)) then
            line = line .. string.format(S(155), tostring(child.MaxActivationDistance))
        elseif child:IsA(S(116)) or child:IsA(S(138)) then
            line = line .. S(57)
        end
        log(line)
        for attrName, attrValue in pairs(child:GetAttributes()) do
            log(indent .. S(109) .. attrName .. S(178) .. tostring(attrValue))
        end
        dumpInstance(child, log, indent .. S(189))
    end
end
return dumpInstance
end
